"""Complete remaining carrot meat dishes, preserves and croquettes."""
import pathlib,json,sqlite3,copy
root=pathlib.Path(__file__).parent
out=root.parent.parent/'outputs/SavorShelf-Content-Repairs'
db=sqlite3.connect(out/'grouped-work.sqlite3')
rows=json.loads((out/'carrot-candidates.json').read_text(encoding='utf-8'))

records={r['sourceId']:r for r in json.loads((root/'content-overrides.json').read_text(encoding='utf-8'))}
aliases={r['id']:r for r in json.loads((root/'recipe-aliases.json').read_text(encoding='utf-8'))}
newids=[]
def src(n):return json.loads(db.execute('select record from recipes where id=?',(rows[n]['id'],)).fetchone()[0])
def I(k,a,u,n,s):return dict(key=k,amount=a,unit=u,name=n,substitution=s)
def carrot(a):return I('carrot',a,'g','carrots, peeled and trimmed','Use the same weight of a different carrot variety; color and sweetness will change.')
def butter(a):return I('butter',a,'g','unsalted butter','Use the same weight of a block-style dairy-free butter alternative.')
def stock(a):return I('stock',a,'ml','unsalted prepared beef stock','Use the same volume of unsalted vegetable stock for a different flavor; check other ingredients before treating the whole recipe as vegetarian.')
def onion(a):return I('onion',a,'g','peeled onion','Use the same weight of trimmed leek, rinsing away any grit.')
def salt(a=3):return I('salt',a,'g','fine salt','Reduce or omit, especially if using salted stock.')
def pepper():return I('pepper',.25,'tsp','ground black pepper','Use the same amount of ground white pepper, or omit.')
def cayenne():return I('cayenne',.125,'tsp','ground cayenne pepper','Omit for a milder soup.')
def sugar(a):return I('sugar',a,'g','granulated sugar','Use the same weight of caster sugar.')
def water(a,k='water'):return I(k,a,'ml','drinking water','Use the same volume of drinking water; water for dough or starch slurry should remain cold.')
def flour(a):return I('flour',a,'g','all-purpose flour','For a sauce, use the same weight of a gluten-free blend labeled for sauces; pastry requires a separate tested gluten-free dough.')
def bread(a):return I('bread',a,'g','plain bread','Use the same weight of gluten-free bread suitable for toasting.')
def oil(a,k='oil'):return I(k,a,'ml','neutral vegetable oil','Use the same volume of refined sunflower or rapeseed oil.')
def yolks(a):return I('yolks',a,'','large pasteurized egg yolks','Use 18 g pasteurized liquid yolk per large yolk; omitting yolk changes the recipe.')
def cream(a):return I('cream',a,'ml','heavy cream','Use the same volume of unsweetened plant cream suitable for cooking.')
def celery(a):return I('celery',a,'g','trimmed celery stalks','Use the same weight of peeled celeriac, cut small and cooked until tender.')
def turnip(a):return I('turnip',a,'g','peeled turnip','Use the same weight of peeled rutabaga; allow extra cooking time until tender.')
def add(n,title,y,t,desc,items,steps,notes,category='Side dishes'):
 s=src(n);r=copy.deepcopy(s['recipe']);r.update(title=title,description=desc,category=category,servings=y,yieldUnit='servings',minutes=t,totalMinutes=t,ingredients=items,steps=steps,sourceStatus='adapted',versionNote='Modern measured adaptation',updatedAt='2026-09-22T18:00:00Z',notes=notes+' Missing amounts, yields and timings are modern adaptation estimates, not recovered historical measurements. Not kitchen-tested. Scaling changes quantities, not cooking times. Cool leftovers promptly in shallow containers and refrigerate within 2 hours at 4°C (40°F) or colder.',source=s['recipe']['source']+' SavorShelf measured adaptation.');r.pop('variants',None);r['sourceAliases']=[]
 records[r['id']]=dict(sourceId=r['id'],bodySha256=s['bodySha256'],recipe=r);newids.append(r['id']);return r
def variant(r,id,label,items,steps):r.setdefault('variants',[]).append(dict(id=id,label=label,ingredients=items,steps=steps))
PUREE='Press the vegetables and their liquid through a coarse sieve into a clean saucepan, or use an immersion blender directly in the deep pan with its head submerged. Do not seal hot soup in a countertop blender.'
def parsley(a=5):return I('parsley',a,'g','fresh parsley, finely chopped','Use the same weight of chives, or omit.')
def milk(a):return I('milk',a,'ml','whole milk','Use the same volume of unsweetened soy milk; flavor differs.')
def rice(a):return I('rice',a,'g','uncooked long-grain white rice','Use the same weight of another white rice; follow its cooking time until tender.')
def eggfinish():return ['Whisk {{yolks}} with {{cream}} in a bowl. Gradually whisk in a little hot soup, then return the mixture to the saucepan.','Stir over low heat until the soup reaches 71°C (160°F), without boiling. Serve promptly.']
def lemon(a,k='lemon'):return I(k,a,'ml','lemon juice','Use the same volume of lime juice for a different flavor.')
def bay():return I('bay',1,'','dried bay leaf','Omit if unavailable.')
def lard(a):return I('lard',a,'g','food-grade pork lard','Use the same weight of neutral vegetable oil.')
def tk(k):return '{{'+k+'}}'
def roux(prefix,b,f,liquid,liquidname='unsalted prepared chicken stock'):
 return [dict(butter(b),key=prefix+'butter'),dict(flour(f),key=prefix+'flour'),I(prefix+'stock',liquid,'ml',liquidname,'Use the same volume of unsalted vegetable stock; flavor differs.')]
def rouxsteps(p):
 return ['In a separate small saucepan, melt '+tk(p+'butter')+'. Stir in '+tk(p+'flour')+' and cook for 2 minutes without browning. Gradually whisk in '+tk(p+'stock')+' until smooth. Simmer gently for 5 minutes, stirring.']
def veloute(prefix='s',volume=120):
 # A small complete mushroom sauce component, with all output used in its parent.
 q=volume/120
 return roux(prefix,10*q,8*q,120*q)+[I(prefix+'mushroom',25*q,'g','cultivated white mushrooms, finely chopped','Use the same weight of cultivated cremini mushrooms.')]
def veloutesteps(p='s'):
 return ['Melt '+tk(p+'butter')+' in a small pan. Add '+tk(p+'mushroom')+' and cook gently for 5 minutes without browning. Stir in '+tk(p+'flour')+' for 2 minutes, then gradually whisk in '+tk(p+'stock')+'. Simmer for 10 minutes, stirring, until smooth. Press through a fine sieve, discard the mushroom pieces and keep the sauce warm.']

def peas(a):return I('peas',a,'g','shelled green peas, fresh or frozen','Use the same weight of frozen peas, adding them without thawing.')
def cornflour(a):return I('cornflour',a,'g','cornstarch (cornflour)','Use the same weight of arrowroot starch, adding it near the end and heating just until thickened.')
def nutmeg():return I('nutmeg',.125,'tsp','ground nutmeg','Use the same amount of ground mace, or omit.')
def boilsteps(shape='1 cm cubes',time='12–18'):
 return ['Cut {{carrot}} into '+shape+'. Bring {{water}} and {{salt}} to a boil. Add the carrots and simmer for '+time+' minutes until tender when pierced with a fork. Drain well.']

def eggs(a):return I('eggs',a,'','large eggs','Use 50 g pasteurized liquid whole egg per egg when separation is not required.')
def crumbs(a):return I('crumbs',a,'g','plain dry breadcrumbs','Use the same weight of dry crumbs from another plain wheat bread.')
def almond(a):return I('almond',a,'g','finely ground blanched almonds','Use the same weight of finely ground sunflower seeds for a different flavor.')
def grease():return I('grease',5,'g','softened unsalted butter for the dish','Use the same weight of a block-style dairy-free butter alternative.')
def peel(a):return I('peel',a,'g','thin yellow lemon peel, white pith removed, finely shredded','Use the same weight of thin orange peel for a different flavor.')
def separated(r):next(i for i in r['ingredients'] if i['key']=='eggs')['substitution']='Use large pasteurized shell eggs if preferred; the whites must remain separate and able to whip.'
CHILL='Transfer to clean shallow food-safe containers. Cool promptly, cover and refrigerate within 2 hours at 4°C (40°F) or colder. Use within 4 days, or freeze promptly. This is not shelf-stable and must not be stored at room temperature.'

def cabbage(a):return I('cabbage',a,'g','green cabbage, core removed','Use the same weight of Savoy cabbage; cook until tender.')
def potato(a):return I('potato',a,'g','peeled potatoes','Use the same weight of another all-purpose potato.')
def lamb(a):return I('lamb',a,'g','boneless lamb breast, trimmed of excess surface fat','Use the same weight of boneless mutton breast; it may need another 30–60 minutes to become tender.')
def brisket(a):return I('beef',a,'g','fresh uncured beef brisket, excess surface fat trimmed','Use the same weight of boneless beef chuck; cook until fork-tender.')
def brown(a):return I('brownsugar',a,'g','soft light brown sugar','Use the same weight of dark brown sugar for a stronger molasses flavor.')
def cinnamon(a=.5):return I('cinnamon',a,'tsp','ground cinnamon','Use half the amount of ground allspice for a different flavor.')
def plainflour(a,k='flour'):return I(k,a,'g','all-purpose flour','Use the same weight of plain wheat flour.')
MEATREF=' Meat cooking guidance: https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/food-safety-basics/safe-temperature-chart .'

r=add(68,'Salt Beef with Carrots, Greens and Suet Dumplings',6,240,'Slow-simmered salt beef is served with carrots, cabbage and rich plain suet dumplings cooked in its broth.',[I('beef',1360,'g','commercially cured uncooked salt-beef brisket, removed from its packaging brine','Use the same weight of uncooked corned-beef brisket; follow any package soaking instructions.'),carrot(300),cabbage(600),water(2000),I('suet',113,'g','food-grade beef suet, membrane removed and finely shredded','Use the same weight of shredded vegetable suet intended for dumplings.'),plainflour(113,'dumplingflour'),I('dumplingsalt',1,'g','fine salt for the dumplings','Omit if the cooking broth is already very salty.'),water(70,'dumplingwater')],['Put {{beef}} in a snug deep pot with {{water}}. Add extra drinking water only if needed to cover the meat by about 2 cm. Bring to a boil, skim surface foam, then cover and maintain a gentle simmer for 2½–3½ hours until a fork enters easily; the meat must also reach at least 74°C (165°F). Keep it covered with liquid, topping up with hot water as needed.','While the meat cooks, cut {{carrot}} into thick 5 cm lengths and {{cabbage}} into wedges. Add the carrots when the meat is nearly tender, with about 40 minutes left.','Mix {{suet}}, {{dumplingflour}} and {{dumplingsalt}}. Add {{dumplingwater}} and bring together into a firm, slightly sticky dough without kneading; if needed, add cold water a teaspoon at a time. Shape into six equal dumplings.','Add the cabbage and dumplings for the final 30 minutes. Simmer gently with the lid on until the vegetables are tender and a dumpling cut open has no raw flour in the center. Use a second pan of ladled hot broth if the pot is too crowded.','Lift out the beef and rest for 10 minutes. Slice across the grain and serve with the vegetables and dumplings, adding a little hot cooking liquid. Discard the remaining very salty broth.'],'The original scan says half a pound EACH suet and flour, not quarter-pound flour. A half-sized dumpling batch retains this rich 1:1 ratio and is divided into six smaller dumplings. Three pounds beef becomes 1.36 kg; the water is increased from three Imperial pints to a practical starting 2 liters, with coverage controlling the final level. Commercially cured beef replaces the source cross-reference to home curing. Carrots are added late so they stay intact. Source kale remains a named variation.','Main dishes')
variant(r,'kale','Salt beef with kale',[dict(i,name='kale leaves, tough stalks removed',substitution='Use the cabbage base if preferred.') if i['key']=='cabbage' else copy.deepcopy(i) for i in r['ingredients']],[t.replace('into wedges','into wide strips').replace('Add the cabbage and dumplings for the final 30 minutes.','Add the dumplings for the final 30 minutes and add the kale for the final 15–20 minutes.').replace('cabbage','kale') for t in r['steps']])
# The ingredient token remains cabbage in the kale variant so all amounts resolve.
r['variants'][-1]['steps']=[t.replace('{{kale}}','{{cabbage}}') for t in r['variants'][-1]['steps']]
r['source']+=' Original scan: Estella Atrutel, recipe107, printed page40, leaf56.'+MEATREF

r=add(69,'Lamb Breast with Carrots, Potatoes and Ginger Gravy',6,210,'Tender lamb breast, carrots and potatoes are coated in a lightly sweet gravy flavored with ginger and cinnamon.',[lamb(1000),salt(5),I('ginger',.5,'tsp','ground ginger','Use the same amount of finely grated fresh ginger for a milder flavor.'),water(1200),carrot(600),potato(750),I('stewfat',25,'g','fat skimmed from the lamb stew for the gravy','Use the same weight of neutral vegetable oil if the stew yields too little fat.'),plainflour(10),brown(18),cinnamon(.25),I('gravy',400,'ml','cooking liquid reserved from the lamb stew','Use the same volume of unsalted prepared lamb or vegetable stock if needed.')],['Cut {{lamb}} into large 6 cm pieces and season with {{salt}} and {{ginger}}. Put in a heavy pot with {{water}}, bring slowly to a simmer, skim foam and cover. Simmer gently for 1½–2 hours, topping up with hot water if needed to keep the meat mostly covered.','Cut {{carrot}} into 3 cm pieces and {{potato}} into 3 cm cubes. Add the carrots when the lamb is almost tender, then the potatoes 10 minutes later. Cover and simmer for another 35–45 minutes, until the vegetables and lamb are tender and the lamb reaches at least 74°C (165°F).','Lift the meat and vegetables onto a warm platter. Let the cooking liquid stand for a few minutes, skim and measure {{stewfat}}, and measure {{gravy}} from beneath the fat.','Heat the measured fat in a small saucepan. Stir in {{flour}} and cook for 3–4 minutes until light brown. Stir in {{brownsugar}} and {{cinnamon}}, then gradually whisk in the measured gravy. Simmer for 5 minutes until smooth.','Return the meat and vegetables to the pot with the sauce and simmer gently for 5 minutes. Serve hot.'],'The source has no meat or carrot weights; 1 kg boneless lamb and 600 g carrots are supplied. Six potatoes become 750 g. Vegetables are added toward the end to preserve their shape. The two tablespoons of skimmed fat become 25 g, and the heaped sugar spoon becomes 18 g. Reserved fat and broth are measured from the same pot, not added twice.','Main dishes');r['source']+=MEATREF

r=add(70,'Brisket and Carrots with Mace and Vinegar Gravy',8,260,'Slow-braised brisket and large carrot pieces are finished with a dark, lightly tangy parsley gravy scented with mace.',[brisket(1800),water(600),salt(6),pepper(),I('mace',.25,'tsp','ground mace','Use the same amount of ground nutmeg.'),carrot(600),I('garlic',5,'g','peeled garlic, finely chopped','Use the same weight of shallot for a different flavor.'),plainflour(20),I('vinegar',15,'ml','white wine vinegar','Use the same volume of cider vinegar.'),parsley(10),I('browning',2.5,'ml','prepared plain gravy browning','Omit for a lighter-colored gravy; do not substitute a full quantity of concentrated soy sauce.'),water(45,'slurrywater')],['Put {{beef}} in a snug heavy pot with {{water}}, {{salt}}, {{pepper}} and {{mace}}. Add enough extra hot water to reach about one-third of the way up the meat if necessary. Bring to a gentle simmer, cover tightly and cook over low heat for 2½ hours, turning the meat once and checking that the pan does not dry.','Cut {{carrot}} into thick pieces about 5 cm long and 2–2.5 cm wide. Add with {{garlic}}, cover and cook for another 45–75 minutes until the carrots are soft and the beef is fork-tender and at least 74°C (165°F). Add a little hot water whenever needed to keep a shallow layer of liquid in the pot.','Transfer the meat and carrots to a warm dish and cover loosely. Skim excess fat from the cooking liquid. Simmer the liquid uncovered to about 600 ml, or add hot water if less remains.','Whisk {{flour}} with {{vinegar}} and {{slurrywater}} to make a smooth slurry. Whisk into the simmering liquid with {{browning}} and {{parsley}}. Simmer for 5–8 minutes, stirring, until thickened and the flour tastes cooked.','Rest the beef for at least 10 minutes before slicing across the grain. Arrange the carrots around it and spoon over the gravy.'],'Four pounds brisket becomes a modern 1.8 kg. The original pint is rounded up to a starting 600 ml for a snug covered pot. Three or four large carrots become 600 g. Missing flour, seasoning and browning amounts are supplied; prepared gravy browning completes the source coloring reference. Adding carrots late replaces three hours of cooking them with the meat, keeping them intact.','Main dishes');r['source']+=MEATREF

r=add(79,'Lamb Breast with Cabbage, Carrots and Cinnamon Gravy',6,210,'Lamb breast is simmered with carrot batons and cabbage, then finished in a lightly sweet cinnamon gravy.',[lamb(1000),salt(5),water(1200),carrot(600),cabbage(600),I('stewfat',25,'g','fat skimmed from the lamb cooking liquid','Use the same weight of neutral vegetable oil if needed.'),plainflour(8),brown(13),cinnamon(.5),I('gravy',400,'ml','cooking liquid reserved from the lamb pot','Use the same volume of unsalted prepared lamb or vegetable stock if needed.')],['Cut {{lamb}} into large 6 cm pieces, season with {{salt}} and put in a heavy pot with {{water}}. Bring to a simmer, skim foam, cover and cook gently for 1½–2 hours until almost tender. Add hot water as needed to keep the meat mostly covered.','Cut {{carrot}} into thick 5 cm batons and {{cabbage}} into wedges. Add both to the pot, cover and simmer for 40–50 minutes until the vegetables and lamb are tender and the lamb reaches at least 74°C (165°F).','Transfer the meat and vegetables to a warm platter. Let the liquid settle briefly, skim and measure {{stewfat}}, then measure {{gravy}} from beneath the fat.','Heat the measured fat in a saucepan and stir in {{flour}} for 3 minutes until lightly browned. Stir in {{brownsugar}} and {{cinnamon}}, then gradually whisk in the measured gravy. Simmer for 5 minutes until smooth.','Pour the sauce over the meat and vegetables and serve together.'],'Weights for the meat and vegetables are supplied because the source provides none. Vegetables are added late instead of boiling for the full two hours. The source tablespoon amounts become 8 g flour and 13 g brown sugar; the half-teaspoon cinnamon is retained. This cabbage version is kept distinct from the potato-and-ginger recipe.','Main dishes');r['source']+=MEATREF

r=add(80,'Carrots with Brisket and Browned Gravy',6,360,'Brisket and soft diced carrots simmer together, then receive a browned roux gravy made with their cooking liquid.',[brisket(900),salt(5),pepper(),carrot(600),water(1500),I('fat',25,'g','beef dripping','Use the same weight of neutral vegetable oil.'),plainflour(16),I('gravy',240,'ml','cooking liquid reserved from the brisket and carrots','Use the same volume of unsalted prepared beef stock if needed.')],['Season {{beef}} with {{salt}} and {{pepper}}. Put in a covered dish and refrigerate for 2 hours at 4°C (40°F) or colder.','Cut {{carrot}} into 1.5 cm cubes. Put the beef and carrots in a snug pot, add boiling {{water}} and add more hot water only if needed to just cover the meat. Bring to a gentle simmer and cook with the lid slightly ajar for 2½–3½ hours until the beef is fork-tender and at least 74°C (165°F). Turn the meat once. Keep enough liquid in the pot to prevent scorching.','Lift out the beef and rest, covered, for 10 minutes. Scoop the carrots into a warm bowl. Skim excess fat from the broth, then simmer the broth uncovered until about 750 ml remains. Measure {{gravy}} from it.','In a separate saucepan, heat {{fat}} and stir in {{flour}}. Cook over medium-low heat for 4–6 minutes until nut-brown, without burning. Gradually whisk in the measured gravy and simmer for 5 minutes until smooth.','Return the carrots and browned gravy to the pot with the remaining reduced broth. Simmer for 5–10 minutes to coat the carrots. Slice the brisket across the grain and serve with the carrots and gravy.'],'The original several-hour seasoning rest is made explicit as two refrigerated hours. Two pounds brisket become 900 g, and two undefined carrot bunches become 600 g. The source half-volume reduction is controlled after cooking to avoid drying the meat. Browning comes from the roux; boiling vegetables in liquid does not itself brown them. The measured cup of broth is taken from the pot, not additional liquid.','Main dishes');r['source']+=MEATREF

r=add(142,'Stewed Veal with Peas, Young Carrots and New Potatoes',8,230,'Roast-browned veal is gently stewed with young vegetables and finished with lemon, tomato and mushroom ketchup.',[I('veal',1600,'g','boneless veal neck or shoulder, in one compact piece','Use the same weight of boneless beef chuck for a different flavor; allow extra time until tender.'),plainflour(25),carrot(450),I('greenonion',60,'g','trimmed green onions','Use the same weight of trimmed leek, rinsed well.'),I('potato',600,'g','small new potatoes, scrubbed','Use the same weight of waxy potatoes cut into 3 cm pieces.'),I('herbs',8,'g','fresh parsley and thyme sprigs, tied with kitchen string','Use parsley stems with one dried bay leaf for a different herb mixture.'),salt(6),pepper(),water(1500),lemon(15),I('tomato',30,'ml','prepared smooth tomato sauce','Use the same volume of plain tomato passata.'),I('mushroomketchup',30,'ml','prepared British-style mushroom ketchup','Use 15 ml soy sauce mixed with 15 ml water for a different flavor; reduce added salt.'),peas(300),water(750,'peawater')],['Heat the oven to 200°C (400°F). Pat {{veal}} dry, coat with {{flour}} and place in a roasting dish. Roast for 40–45 minutes until the surface is browned; this does not complete the cooking.','Move the browned meat to a snug heavy pot. Cut {{carrot}} into 5 cm lengths, {{greenonion}} into 3 cm pieces and halve any large {{potato}}. Reserve the vegetables for later.','Add {{herbs}}, {{salt}}, {{pepper}} and boiling {{water}} to the meat. Add more hot water only if needed to just cover it. Bring to a gentle simmer, cover and stew for 1½ hours, checking occasionally that liquid remains.','Add the reserved carrots, onions and potatoes. Simmer covered for another 30–45 minutes until the vegetables are tender and the veal is fork-tender and at least 74°C (165°F). If the meat needs longer, lift out tender vegetables and return them at the end.','Meanwhile, bring {{peawater}} to a boil in another pan. Add {{peas}}, simmer for 3–5 minutes until tender and drain.','Lift the meat and vegetables into a warm deep serving dish, discard the herb bundle and skim excess fat from the gravy. Simmer the gravy uncovered until about 750 ml remains, then stir in {{lemon}}, {{tomato}} and {{mushroomketchup}}.','Rest the meat for 10 minutes, slice and arrange with the vegetables and cooked peas. Pour over the hot gravy and serve.'],'The source roast-then-stew sequence is retained. Three to four pounds veal become 1.6 kg; fifteen young carrots, twelve potatoes and one pint of shelled peas become modern 450 g, 600 g and 300 g choices. Vegetables are added later than the source to avoid overcooking. Prepared tomato sauce and mushroom ketchup make the condiment references self-contained. The optional forcemeat garnish is preserved in a complete named variation.','Main dishes');r['source']+=MEATREF
vitems=copy.deepcopy(r['ingredients'])+[I('ballmeat',250,'g','ground veal for the optional forcemeat balls','Use the same weight of ground beef.'),I('ballcrumb',30,'g','plain dry breadcrumbs for the balls','Use the same weight of gluten-free dry breadcrumbs.'),I('ballegg',1,'','large egg for the balls','Use 50 g pasteurized liquid whole egg.'),I('ballparsley',5,'g','fresh parsley, finely chopped','Use the same weight of chives.'),I('ballsalt',2,'g','fine salt for the balls','Reduce or omit.'),I('ballpepper',.125,'tsp','ground black pepper for the balls','Omit for a milder flavor.')]
vsteps=copy.deepcopy(r['steps']);vsteps.insert(4,'For the optional garnish, mix {{ballmeat}}, {{ballcrumb}}, {{ballegg}}, {{ballparsley}}, {{ballsalt}} and {{ballpepper}} with clean hands. Shape into twelve small balls. Add to the gently simmering stew for 15–20 minutes, until the centers reach at least 74°C (165°F). Handle raw meat separately from cooked food.');vsteps[-1]+=' Arrange the cooked forcemeat balls around the meat.';variant(r,'forcemeat-balls','Veal stew with forcemeat balls',vitems,vsteps)

r=add(29,'Zanahorias Encantadas with Spiced Nuts',12,105,'Hollow carrot pieces are glazed in a sweet syrup and served with a soft mixture of toasted nuts, warm spices and orange-flower water.',[carrot(600),water(1500),I('honey',450,'g','mild honey','Use the complete sugar-syrup variation for a different flavor.'),water(250,'syrupwater'),I('almonds',50,'g','blanched almonds','Use the same weight of blanched hazelnuts for a different flavor.'),I('walnuts',35,'g','shelled walnuts','Use the same weight of pecans.'),I('pinenuts',20,'g','pine nuts','Use the same weight of blanched slivered almonds.'),I('flowerwater',5,'ml','food-grade orange-flower water','Use the same volume of food-grade rose water for a different floral flavor.'),cinnamon(.5),I('ginger',.25,'tsp','ground ginger','Use half the amount of ground allspice for a different flavor.'),I('cloves',.125,'tsp','ground cloves','Omit for a milder spice mixture.'),I('reservedsyrup',120,'ml','warm syrup reserved from the carrot pan','Use the same volume of the sugar-syrup variation if making that version.')],['Choose thick straight {{carrot}} and cut into 4–5 cm lengths. Working carefully with a narrow vegetable corer from each end, remove the central core without splitting the sides. Keep the removed cores for another dish. Bring {{water}} to a simmer, add the hollow carrots and cook gently for 15–25 minutes until tender but still intact. Drain carefully.','Bring {{honey}} and {{syrupwater}} to a gentle boil in a wide saucepan, skim any foam and simmer for 2 minutes. Strain through a fine heatproof sieve into a clean pan and let cool for 10 minutes. Add the drained carrots.','Simmer gently for 20–30 minutes, turning carefully, until the carrots are glazed and the syrup coats a spoon. Add water a tablespoon at a time if it thickens before the carrots are evenly glazed. Lift the carrots onto a serving dish and measure {{reservedsyrup}} from the pan.','While the carrots simmer, toast {{almonds}} and {{walnuts}} in a dry pan over medium-low heat for 3–5 minutes, stirring, then cool and chop finely. Toast {{pinenuts}} separately for 1–2 minutes, watching closely, and chop.','Put the measured reserved syrup in a small pan, bring to a gentle simmer and stir in the toasted nuts. Cook for 1–2 minutes until it forms a soft, spoonable mixture. Remove from heat and stir in {{flowerwater}}, {{cinnamon}}, {{ginger}} and {{cloves}}.','Spoon the soft nut mixture into and around the hollow carrots as a modern serving choice. Spoon over the remaining carrot syrup. Serve small portions warm or cool.',CHILL],'The historical word miel is interpreted as honey here; a complete sugar-syrup variation retains the confectionery-syrup possibility. Historical cuartillos are not claimed as verified conversions: the honey, water, nuts and flavorings are supplied modern amounts. The full scanned continuation was checked. Hollow carrots and the spiced nut mixture are explicit, but the final filling/plating action is supplied rather than presented as a recovered instruction. Boiling is shortened to preserve the carrot tubes. This is a refrigerated dessert, not a shelf-stable preserve.','Desserts')
vitems=[dict(i,key='syrupsugar',name='granulated sugar for the syrup',substitution='Use the same weight of caster sugar.') if i['key']=='honey' else dict(i,name='reserved sugar syrup from the carrot pan',substitution='Use the syrup made in this variation.') if i['key']=='reservedsyrup' else copy.deepcopy(i) for i in r['ingredients']];vsteps=[t.replace('{{honey}}','{{syrupsugar}}') for t in r['steps']];variant(r,'sugar-syrup','Carrots in sugar syrup with spiced nuts',vitems,vsteps);r['source']+=' Original scans checked: printed pages217–218, leaves224–225.'

r=add(94,'Sárgarépa Kalarábival with Breaded Brain Croquettes',6,110,'Carrot and kohlrabi crescents in parsley sauce are served with small wafer-wrapped, breaded veal-brain croquettes.',[carrot(350),I('kohlrabi',350,'g','peeled kohlrabi','Use the same weight of peeled young turnip for a different flavor.'),butter(40),parsley(8),plainflour(12),I('vegstock',350,'ml','unsalted prepared beef or vegetable stock for the vegetables','Use the same volume of unsalted prepared chicken stock.'),sugar(5),I('brains',300,'g','food-grade veal brains, cleaned by the butcher, from an inspected meat supplier','Use the same weight of food-grade lamb brains from an inspected supplier; the flavor will differ.'),water(1000),I('poachsalt',3,'g','fine salt for poaching','Reduce or omit.'),I('fbutter',20,'g','unsalted butter for the filling','Use the same weight of neutral vegetable oil.'),I('fparsley',5,'g','fresh parsley for the filling, finely chopped','Use the same weight of chives.'),I('fsalt',1,'g','fine salt for the filling','Reduce or omit.'),pepper(),I('fcrumb',40,'g','plain dry breadcrumbs for the filling','Use the same weight of gluten-free dry breadcrumbs.'),I('fstock',60,'ml','unsalted prepared beef or vegetable stock for the filling','Use the same volume of unsalted prepared chicken stock.'),I('wafers',6,'','plain unsweetened edible starch wafer sheets, about 15 cm across','Use six plain rice-paper wrappers of similar size; soften according to their package instructions and expect a different crust.'),water(200,'dipwater'),eggs(2),plainflour(40,'coatflour'),I('coatcrumb',100,'g','plain dry breadcrumbs for coating','Use the same weight of gluten-free dry breadcrumbs.'),oil(600,'fryoil')],['Bring {{water}} and {{poachsalt}} to a gentle simmer. Add {{brains}} and poach for about 10–15 minutes, until firm and at least 71°C (160°F) in the center. Lift out, drain and spread on a shallow tray. Cool until safe to handle, remove any remaining fine membrane and chop. Keep utensils for the raw brains separate from cooked food.','Melt {{fbutter}} in a small pan. Add {{fparsley}} and the chopped brains, then {{fsalt}}, {{pepper}}, {{fcrumb}} and {{fstock}}. Stir over low heat for 3–5 minutes until thick enough to hold its shape. Spread in a shallow dish, cool briefly and refrigerate for about 20 minutes until firm enough to portion.','Meanwhile, slice {{carrot}} and {{kohlrabi}} about 5 mm thick and cut into small half-moons. Melt {{butter}} in a wide covered pan, add the vegetables and {{parsley}}, then 2 tablespoons of the measured {{vegstock}}. Cover and cook gently for 10 minutes without browning.','Stir in {{flour}} for 2 minutes, add the remaining measured stock and {{sugar}}, and simmer for 10–15 minutes until the vegetables are tender and the sauce lightly coats them. Keep hot over low heat while frying, adding a little water if needed.','Cut {{wafers}} in half. Put {{dipwater}} in a shallow plate and briefly dampen one wafer half at a time, just until flexible. Divide the filling into twelve portions. Put one on each half, fold in the sides and roll into a small packet; pat away any surface water.','Beat {{eggs}} in a shallow bowl. Put {{coatflour}} and {{coatcrumb}} in separate bowls. Coat each packet lightly in flour, then egg, then crumbs, pressing gently.','Heat {{fryoil}} to 170°C (340°F) in a deep, heavy pan, with the oil no more than one-third of the pan depth. Fry a few packets at a time for about 4–6 minutes, turning as needed, until golden and at least 74°C (165°F) in the center. Drain on a rack. Serve promptly with the hot vegetables.'],'The original scan specifies butter in both mixtures and plain edible wafers, not bacon fat or sweet wafer cookies. Species is not stated in the original paragraph; veal is the explicit modern choice. All missing amounts, poaching and frying temperatures and small-portion sizes are supplied. The coating sequence is changed to flour, egg, crumbs for reliable adhesion. The complete brain-croquette accompaniment is retained rather than omitted.','Main dishes')
